INSERT INTO rol_permiso(tenant_id,id_rol,id_permiso) SELECT r.tenant_id,r.id_rol,p.id_permiso FROM rol r CROSS JOIN permiso p WHERE r.nombre='Administrador' AND p.codigo IN ('usuarios.ver','usuarios.crear','usuarios.editar','usuarios.inactivar','roles.ver','roles.asignar','clientes.ver','clientes.crear','clientes.editar','clientes.inactivar','geografia.ver','ciudades.gestionar','sucursales.gestionar','categorias.ver','categorias.gestionar','prendas.ver','prendas.gestionar','pos.vender','ventas.ver','bitacora.ver','offline.operar','conflictos.resolver','reportes.ver','reportes.ia','cambios.gestionar') ON CONFLICT DO NOTHING;
INSERT INTO rol_permiso(tenant_id,id_rol,id_permiso) SELECT r.tenant_id,r.id_rol,p.id_permiso FROM rol r CROSS JOIN permiso p WHERE r.nombre='Encargado de Sucursal' AND p.codigo IN ('clientes.ver','clientes.crear','geografia.ver','categorias.ver','prendas.ver','prendas.gestionar','pos.vender','ventas.ver','offline.operar','conflictos.resolver','reportes.ver','reportes.ia','cambios.gestionar') ON CONFLICT DO NOTHING;
INSERT INTO rol_permiso(tenant_id,id_rol,id_permiso) SELECT r.tenant_id,r.id_rol,p.id_permiso FROM rol r CROSS JOIN permiso p WHERE r.nombre='Cajero (POS)' AND p.codigo IN ('clientes.ver','clientes.crear','geografia.ver','categorias.ver','prendas.ver','pos.vender','ventas.ver','offline.operar','cambios.gestionar') ON CONFLICT DO NOTHING;
